INSERT INTO collection_pages VALUES('2bde314c20643602a713b7b5cb3a2ba5e8d435f5bdb904a76b20f5d29e6a033a','a0a8e5ee717c18dc80c63efa6be0ff62ead98579797b14bda7f1016f532716a6','{"hasNext":false,"items":[{"author":{"account":null,"email":"sivhok.chhoem@tsc.gov.kh","name":"sivhok"},"authoredDate":"2026-10-08T12:28:40Z","committedDate":"2026-10-08T12:28:40Z","committer":{"account":null,"email":"sivhok.chhoem@tsc.gov.kh","name":"sivhok"},"observedAt":"2026-10-09T00:59:00.000Z","repositoryId":1410155908,"sha":"9a522bed2335c9848a72d11a33e8751bda99777a"},{"author":{"account":null,"email":"sivhok.chhoem@tsc.gov.kh","name":"sivhok"},"authoredDate":"2026-10-08T12:22:05Z","committedDate":"2026-10-08T12:22:05Z","committer":{"account":null,"email":"sivhok.chhoem@tsc.gov.kh","name":"sivhok"},"observedAt":"2026-10-09T00:59:00.000Z","repositoryId":1410155908,"sha":"47e891225f84df5009a643cb860229120d4096eb"}],"observedAt":"2026-10-09T00:59:00.000Z","raw":[{"author":null,"comments_url":"https://api.github.com/repos/Hooksmith/react-new/commits/9a522bed2335c9848a72d11a33e8751bda99777a/comments","commit":{"author":{"date":"2026-10-08T12:28:40Z","email":"sivhok.chhoem@tsc.gov.kh","name":"sivhok"},"comment_count":0,"committer":{"date":"2026-10-08T12:28:40Z","email":"sivhok.chhoem@tsc.gov.kh","name":"sivhok"},"message":"fix: refuse to start with a missing or weak SESSION_SECRET\n\nNext.js only logs errors thrown from the instrumentation hook and keeps\nserving, so a misconfigured container stayed \"running\" while every\nrequest failed. Both zones now exit(1) at boot when the secret is missing\nor shorter than 32 characters, so Kubernetes/compose surface the failure.\n\nAlso make the compose host port configurable (SHELL_PORT) for machines\nwhere 3000 is already taken, and document it in the README.\n\nCo-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>","tree":{"sha":"e7784be9b31c17ca8766d8dd31986d59fdcd475f","url":"https://api.github.com/repos/Hooksmith/react-new/git/trees/e7784be9b31c17ca