INSERT INTO collection_pages VALUES('76b8550a1561034c5a9aadcdb5bbd1f36bce6e6ad996058912ee6c7af2039e1b','e3952b4243fd972d2e3f224e4c8b4a43362bae76ee36bdf0b95bb51cdadc4210','{"hasNext":false,"items":[{"author":{"account":{"login":"duchenean","providerType":"User"},"email":"antoine.duchene@imio.be","name":"Antoine Duchêne"},"authoredDate":"2026-10-08T11:17:36Z","committedDate":"2026-10-08T11:17:36Z","committer":{"account":{"login":"duchenean","providerType":"User"},"email":"antoine.duchene@imio.be","name":"Antoine Duchêne"},"observedAt":"2026-10-09T00:59:02.256Z","repositoryId":1410198219,"sha":"927cd716bf64c51ba76614d5d4cfed2459165e3d"}],"observedAt":"2026-10-09T00:59:02.256Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/9050997?v=4","events_url":"https://api.github.com/users/duchenean/events{/privacy}","followers_url":"https://api.github.com/users/duchenean/followers","following_url":"https://api.github.com/users/duchenean/following{/other_user}","gists_url":"https://api.github.com/users/duchenean/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/duchenean","id":9050997,"login":"duchenean","node_id":"MDQ6VXNlcjkwNTA5OTc=","organizations_url":"https://api.github.com/users/duchenean/orgs","received_events_url":"https://api.github.com/users/duchenean/received_events","repos_url":"https://api.github.com/users/duchenean/repos","site_admin":false,"starred_url":"https://api.github.com/users/duchenean/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/duchenean/subscriptions","type":"User","url":"https://api.github.com/users/duchenean","user_view_type":"public"},"comments_url":"https://api.github.com/repos/IMIO/imio.pdfviewer/commits/927cd716bf64c51ba76614d5d4cfed2459165e3d/comments","commit":{"author":{"date":"2026-10-08T11:17:36Z","email":"antoine.duchene@imio.be","name":"Antoine Duchêne"},"comment_count":0,"committer":{"date":"2026-10-08T11:17:36Z","email":"antoine.duchene@imio.be","name":"Antoine Duchêne"},"message":"Add imio.pdfviewer: the pat-pdf-viewer pattern\n\nMove the PDF viewer of plonemeeting.portal.core into its own Plone 6.2\nadd-on, as a patternslib pattern shipped as a Module Federation remote.\n\n- React 19 instead of Preact. Layout, markup, classes, icons, labels and\n  behaviour stay the same.\n- The pdf.js worker loads from the bundle, not from cdnjs.cloudflare.com.\n- The .pdf-viewer styles come unchanged from plonetheme.deliberations.\n- @patternslib/patternslib 9.10.7 and @plone/mockup 5.6.10, as in\n  plone.staticresources 3.0.6 (Plone 6.2.2).\n- The bundle is committed and reproducible: CI rebuilds it and fails when\n  it is out of date.\n\nCo-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>","tree":{"sha":"1d632a445f927b331c3be7daf09948a597d0f4d9","url":"https://api.github.com/repos/IMIO/imio.pdfviewer/git/trees/1d632a445f927b331c3be7daf09948a597d0f4d9"},"url":"https://api.github.com/repos/IMIO/imio.pdfviewer/git/commits/927cd716bf64c51ba76614d5d4cfed2459165e3d","verification":{"payload":"tree 1d632a445f927b331c3be7daf09948a597d0f4d9\nauthor Antoine Duchêne <antoine.duchene@imio.be> 1791458256 +0200\ncommitter Antoine Duchêne <antoine.duchene@imio.be> 1791458256 +0200\n\nAdd imio.pdfviewer: the pat-pdf-viewer pattern\n\nMove the PDF viewer of plonemeeting.portal.core into its own Plone 6.2\nadd-on, as a patternslib pattern shipped as a Module Federation remote.\n\n- React 19 instead of Preact. Layout, markup, classes, icons, labels and\n  behaviour stay the same.\n- The pdf.js worker loads from the bundle, not from cdnjs.cloudflare.com.\n- The .pdf-viewer styles come unchanged from plonetheme.deliberations.\n- @patternslib/patternslib 9.10.7 and @plone/mockup 5.6.10, as in\n  plone.staticresources 3.0.6 (Plone 6.2.2).\n- The bundle is committed and reproducible: CI rebuilds it and fails when\n  it is out of date.\n\nCo-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>\n","reason":"valid","signature":"-----BEGIN PGP SIGNATURE-----\n\niHUEAB